'use client';

import { useEffect, useState, useCallback, useRef } from 'react';
import { useSettings } from './Settings';
import { useLanguage } from '@/lib/i18n';
import { logEnforcementDecision } from '@/lib/enforcement-log';
import { trackEvent } from '@/lib/analytics';
import { getSafetyStatus } from '@/lib/safety-status';
import type { SafetyRiskLevel } from '@/lib/safety-status';
import type { ExecutionRequest, GovernanceEvidenceReceipt } from '@/lib/ai';
import type { ExecutionDiagnostic } from '@/lib/execution-diagnostics';

export interface ProcessingExecutionOverrides {
    mode?: ExecutionRequest['mode'];
    cvfPhase?: ExecutionRequest['cvfPhase'];
    cvfRiskLevel?: ExecutionRequest['cvfRiskLevel'];
    skillPreflightDeclaration?: ExecutionRequest['skillPreflightDeclaration'];
    skillPreflightRecordRef?: ExecutionRequest['skillPreflightRecordRef'];
    skillIds?: ExecutionRequest['skillIds'];
    fileScope?: ExecutionRequest['fileScope'];
    aiCommit?: ExecutionRequest['aiCommit'];
}

interface ProcessingScreenProps {
    templateName: string;
    templateId?: string;
    inputs?: Record<string, string>;
    intent?: string;
    executionOverrides?: ProcessingExecutionOverrides;
    onComplete: (output: string, evidenceReceipt?: GovernanceEvidenceReceipt) => void;
    onCancel: () => void;
}

export interface GovernanceEvidenceState {
    provider?: string;
    model?: string;
    decision?: string;
    riskLevel?: string;
    providerDecision?: string;
    policySnapshotId?: string;
    envelopeId?: string;
    receiptId?: string;
    evidenceMode?: string;
    knowledgeSource?: string;
    knowledgeInjected?: boolean;
    knowledgeCollectionId?: string | null;
    knowledgeChunkCount?: number;
    validationHint?: string;
    approvalId?: string;
}

type FalsePositiveReportState = 'idle' | 'submitting' | 'submitted' | 'error';

function mapSettingsProviderToExecutionProvider(provider?: string): ExecutionRequest['provider'] | undefined {
    if (!provider) {
        return undefined;
    }

    if (provider === 'anthropic') {
        return 'claude';
    }

    return provider as ExecutionRequest['provider'];
}

function resolveTemplateGuardAction(overrides?: ProcessingExecutionOverrides): string {
    const phase = overrides?.cvfPhase?.trim().toUpperCase();
    const hasBuildPreflight =
        Boolean(overrides?.skillPreflightDeclaration) ||
        Boolean(overrides?.skillPreflightRecordRef) ||
        Boolean(overrides?.skillIds?.length) ||
        Boolean(overrides?.fileScope?.length);

    if (phase === 'BUILD' || phase === 'PHASE C' || phase === 'C' || hasBuildPreflight) {
        return 'build template execution request';
    }

    return 'analyze template execution request';
}

function resolveApprovalSafeHint(reasons: unknown, isVi: boolean): string | null {
    const reasonText = Array.isArray(reasons) ? reasons.join(' ') : String(reasons ?? '');
    const normalized = reasonText.toLowerCase();

    const hints = [
        {
            pattern: /skill preflight|preflight/i,
            vi: 'Bạn có thể bổ sung khai báo phạm vi/kỹ năng trước khi gửi lại, hoặc giữ yêu cầu này trong hàng chờ review.',
            en: 'You can add the missing scope or skill declaration before retrying, or keep this request in the review queue.',
        },
        {
            pattern: /budget|quota|cost/i,
            vi: 'Bạn có thể giảm phạm vi xử lý hoặc chờ admin xem xét giới hạn trước khi chạy lại.',
            en: 'You can narrow the task scope or wait for an admin to review the limit before retrying.',
        },
        {
            pattern: /r3|r4|approval|human approval|executive/i,
            vi: 'Bạn có thể gửi review như hiện tại, hoặc tách yêu cầu thành bước lập kế hoạch rủi ro thấp hơn trước.',
            en: 'You can keep this in review, or split the task into a lower-risk planning step first.',
        },
    ];

    const match = hints.find(hint => hint.pattern.test(normalized));
    return match ? (isVi ? match.vi : match.en) : null;
}

// One attempt per admitted logical task; Cancel, unmount or task replacement invalidates all of its
// async work. Client abort is best effort: correctness never depends on the transport honouring it.
interface Attempt {
    active: boolean;
    delivered: boolean;
    cancelRequested: boolean;
    controller: AbortController;
    timeouts: Set<ReturnType<typeof setTimeout>>;
    intervals: Set<ReturnType<typeof setInterval>>;
}

type CompleteArgs = [output: string, evidenceReceipt?: GovernanceEvidenceReceipt];

function createAttempt(): Attempt {
    return {
        active: true,
        delivered: false,
        cancelRequested: false,
        controller: new AbortController(),
        timeouts: new Set(),
        intervals: new Set(),
    };
}

function stopAttempt(attempt: Attempt) {
    attempt.active = false;
    attempt.controller.abort();
    attempt.timeouts.forEach(id => clearTimeout(id));
    attempt.intervals.forEach(id => clearInterval(id));
    attempt.timeouts.clear();
    attempt.intervals.clear();
}

function scheduleInAttempt(attempt: Attempt, run: () => void, delay: number) {
    const id = setTimeout(() => {
        attempt.timeouts.delete(id);
        if (attempt.active) run();
    }, delay);
    attempt.timeouts.add(id);
    return id;
}

// At-most-once delivery per active attempt for both manual and automatic completion.
function deliverOnce(attempt: Attempt, onComplete: (...args: CompleteArgs) => void, args: CompleteArgs) {
    if (!attempt.active || attempt.delivered) return;
    attempt.delivered = true;
    onComplete(...args);
}

// Content key of the request-determining values, so object identity never restarts a task.
function stableKey(value: unknown): string {
    if (Array.isArray(value)) return `[${value.map(stableKey).join(',')}]`;
    if (value && typeof value === 'object') {
        const record = value as Record<string, unknown>;
        return `{${Object.keys(record).sort().map(key => `${JSON.stringify(key)}:${stableKey(record[key])}`).join(',')}}`;
    }
    return JSON.stringify(value) ?? 'undefined';
}

export function ProcessingScreen({
    templateName,
    templateId,
    inputs,
    intent,
    executionOverrides,
    onComplete,
    onCancel
}: ProcessingScreenProps) {
    const { settings, isLoaded } = useSettings();
    const { language } = useLanguage();
    const isVi = language === 'vi';
    const [progress, setProgress] = useState(0);
    const [status, setStatus] = useState(isVi ? 'Đang khởi tạo...' : 'Initializing...');
    const [error, setError] = useState<string | null>(null);
    const [guidedResponse, setGuidedResponse] = useState<string | null>(null);
    const [isRealExecution] = useState(() => Boolean(inputs && intent && Object.keys(inputs).length > 0));
    // W92-T1: Approval request state
    const [approvalRequestId, setApprovalRequestId] = useState<string | null>(null);
    const [approvalSubmitting, setApprovalSubmitting] = useState(false);
    const [enforcementStatus, setEnforcementStatus] = useState<string | null>(null);
    const [approvalSafeHint, setApprovalSafeHint] = useState<string | null>(null);
    const [falsePositiveReportState, setFalsePositiveReportState] = useState<FalsePositiveReportState>('idle');
    // W94-T1: Risk badge state
    const [executionRiskLevel, setExecutionRiskLevel] = useState<SafetyRiskLevel | null>(null);
    // W114-T1 CP5: user-visible governance evidence from the live execute route
    const [governanceEvidence, setGovernanceEvidence] = useState<GovernanceEvidenceState | null>(null);
    const [executionDiagnostic, setExecutionDiagnostic] = useState<ExecutionDiagnostic | null>(null);
    // W96-T1: Completion state — set when success+riskLevel; suppresses 300ms path
    const [completion, setCompletion] = useState<{ attempt: Attempt; output: string; receipt?: GovernanceEvidenceReceipt } | null>(null);
    const executionProvider = mapSettingsProviderToExecutionProvider(settings.preferences?.defaultProvider);
    const selectedModel = settings.preferences?.defaultProvider
        ? settings.providers?.[settings.preferences.defaultProvider]?.selectedModel
        : undefined;

    // Callbacks and presentation are read at use time so their identity never restarts a task.
    const currentView = {
        onComplete,
        onCancel,
        isVi,
        request: {
            templateId,
            templateName,
            inputs,
            intent,
            executionOverrides,
            mode: settings.preferences.defaultExportMode || 'governance',
            executionProvider,
            selectedModel,
        },
    };
    const latest = useRef(currentView);
    useEffect(() => {
        latest.current = currentView;
    });
    const attemptRef = useRef<Attempt | null>(null);
    const taskKey = stableKey(currentView.request);

    // Real API execution for one attempt; nothing from an abandoned attempt reaches the UI.
    const executeReal = useCallback(async (attempt: Attempt) => {
        const { request, isVi } = latest.current;
        const { templateId, templateName, inputs, intent, executionOverrides, mode, executionProvider, selectedModel } = request;
        if (!inputs || !intent) return false;

        try {
            setStatus(isVi ? 'Đang kết nối AI...' : 'Connecting to AI provider...');
            setProgress(10);
            const aiCommit = executionOverrides?.aiCommit || {
                commitId: `web-ui-${templateId || templateName}-${Date.now()}`,
                agentId: 'cvf-web-ui',
                timestamp: Date.now(),
                description: `UI execution for ${templateName}`,
            };
            const action = resolveTemplateGuardAction(executionOverrides);

            const response = await fetch('/api/execute', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                signal: attempt.controller.signal,
                body: JSON.stringify({
                    templateId: templateId || templateName,
                    templateName,
                    inputs,
                    intent,
                    mode,
                    action,
                    ...(executionProvider ? { provider: executionProvider } : {}),
                    ...(selectedModel ? { model: selectedModel } : {}),
                    ...executionOverrides,
                    aiCommit,
                }),
            });

            if (!attempt.active) return false;
            setProgress(50);
            setStatus(isVi ? 'Đang xử lý phản hồi...' : 'Processing response...');

            const data = await response.json();
            if (!attempt.active) return false;
            const enforcement = data.enforcement;
            const receipt = data.governanceEvidenceReceipt as GovernanceEvidenceReceipt | undefined;
            const diagnostic = data.diagnostic as ExecutionDiagnostic | undefined;
            setExecutionDiagnostic(diagnostic ?? null);
            setFalsePositiveReportState('idle');
            setGovernanceEvidence({
                provider: receipt?.provider || data.provider,
                model: receipt?.model || data.model,
                decision: receipt?.decision || enforcement?.status,
                riskLevel: receipt?.riskLevel || enforcement?.riskGate?.riskLevel,
                providerDecision: receipt?.routingDecision || data.providerRouting?.decision,
                policySnapshotId: receipt?.policySnapshotId || data.policySnapshotId || data.governanceEnvelope?.policySnapshotId,
                envelopeId: receipt?.envelopeId || data.governanceEnvelope?.envelopeId,
                receiptId: receipt?.receiptId,
                evidenceMode: receipt?.evidenceMode,
                knowledgeSource: receipt?.knowledgeSource || data.knowledgeInjection?.source,
                knowledgeInjected: receipt?.knowledgeInjected ?? data.knowledgeInjection?.injected,
                knowledgeCollectionId: receipt?.knowledgeCollectionId ?? data.knowledgeInjection?.collectionId,
                knowledgeChunkCount: receipt?.knowledgeChunkCount ?? data.knowledgeInjection?.chunkCount,
                validationHint: receipt?.validationHint || data.outputValidation?.qualityHint,
                approvalId: receipt?.approvalId || data.approvalId,
            });
            // W94-T1: Extract risk level for badge (R4 → R3 cap for safety-status.ts compat)
            const rawRisk = enforcement?.riskGate?.riskLevel as string | undefined;
            const badgeLevel: SafetyRiskLevel | null =
                rawRisk === 'R0' || rawRisk === 'R1' || rawRisk === 'R2' ? rawRisk :
                rawRisk === 'R3' || rawRisk === 'R4' ? 'R3' : null;
            if (badgeLevel) setExecutionRiskLevel(badgeLevel);
            if (enforcement) {
                logEnforcementDecision({
                    source: 'api_execute',
                    mode,
                    enforcement,
                    context: {
                        templateId: templateId || templateName,
                        templateName,
                        provider: data.provider,
                        model: data.model,
                    },
                });
            }

            setProgress(90);
            setStatus(isVi ? 'Đang hoàn tất...' : 'Finalizing...');

            if (data.success && data.output) {
                setProgress(100);
                if (badgeLevel) {
                    // W96-T1: persist badge — completion-banner + useEffect auto-advance
                    setCompletion({ attempt, output: data.output, receipt });
                } else {
                    scheduleInAttempt(attempt, () => deliverOnce(attempt, latest.current.onComplete, [data.output, receipt]), 300);
                }
                return true;
            }

            if (enforcement?.status === 'CLARIFY') {
                const missing = enforcement.specGate?.missing
                    ?.map((field: { label?: string }) => field.label || 'field')
                    .join(', ');
                setError(missing
                    ? (isVi ? `Thiếu thông tin bắt buộc: ${missing}` : `Missing required input: ${missing}`)
                    : (isVi ? 'Cần thêm thông tin trước khi thực thi.' : 'Spec needs additional info before execution.'));
                return true;
            }

            if (enforcement?.status === 'BLOCK') {
                setError(data.error || (isVi ? 'Bị chặn bởi CVF.' : 'Blocked by CVF enforcement.'));
                if (data.guidedResponse) setGuidedResponse(data.guidedResponse);
                return true;
            }

            if (enforcement?.status === 'NEEDS_APPROVAL') {
                setError(data.error || (isVi ? 'Cần phê duyệt trước khi thực thi.' : 'Approval required before execution.'));
                if (data.guidedResponse) setGuidedResponse(data.guidedResponse);
                setEnforcementStatus('NEEDS_APPROVAL');
                setApprovalSafeHint(resolveApprovalSafeHint(enforcement.reasons, isVi));
                if (data.approvalId) setApprovalRequestId(data.approvalId);
                return true;
            }

            // CP3: guard BLOCK must not trigger mock fallback — guard decision is a classified non-counted outcome
            if (data.guardResult?.finalDecision === 'BLOCK') {
                setError(data.error || (isVi ? 'Bị chặn bởi hệ thống bảo vệ.' : 'Blocked by guard pipeline.'));
                return true;
            }

            // If real execution fails, render the classified failure truthfully.
            if (diagnostic) {
                const nextAction = diagnostic.userAction.replaceAll('_', ' ');
                setError(isVi
                    ? `${diagnostic.safeMessage} Bước tiếp theo: ${nextAction}.`
                    : `${diagnostic.safeMessage} Next action: ${nextAction}.`);
                trackEvent('task_recovery_prompted', {
                    method: 'execution_diagnostic',
                    class: diagnostic.class,
                    userAction: diagnostic.userAction,
                    receiptId: diagnostic.receiptId ?? receipt?.receiptId,
                    templateId,
                });
                return true;
            }

            setError(data.error || (isVi
                ? 'Thực thi API thất bại. Không tạo kết quả mẫu thay thế.'
                : 'API execution failed. No mock output was generated.'));
            return true;
        } catch (err) {
            if (!attempt.active) return false;
            setExecutionDiagnostic(null);
            const message = err instanceof Error ? err.message : 'Network error';
            setError(isVi
                ? `${message}. Không tạo kết quả mẫu thay thế.`
                : `${message}. No mock output was generated.`);
            return true;
        }
    }, []);

    const canReportFalsePositive =
        Boolean(governanceEvidence?.receiptId) &&
        (governanceEvidence?.decision === 'BLOCK' || governanceEvidence?.decision === 'CLARIFY');

    useEffect(() => {
        const decision = governanceEvidence?.decision;
        if (!governanceEvidence?.receiptId || !decision) return;
        if (decision !== 'BLOCK' && decision !== 'CLARIFY' && decision !== 'NEEDS_APPROVAL') return;
        trackEvent('task_recovery_prompted', {
            receiptId: governanceEvidence.receiptId,
            decision,
            riskLevel: governanceEvidence.riskLevel,
            templateId,
        });
    }, [governanceEvidence?.decision, governanceEvidence?.receiptId, governanceEvidence?.riskLevel, templateId]);

    const reportFalsePositive = useCallback(async () => {
        if (!canReportFalsePositive || !governanceEvidence?.receiptId || !governanceEvidence.decision) return;

        setFalsePositiveReportState('submitting');
        try {
            const response = await fetch('/api/governance/false-positive-report', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    receiptId: governanceEvidence.receiptId,
                    envelopeId: governanceEvidence.envelopeId,
                    decision: governanceEvidence.decision,
                    riskLevel: governanceEvidence.riskLevel,
                    reason: error ?? undefined,
                    templateId: templateId || templateName,
                    routeId: '/api/execute',
                }),
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok || !data.success) {
                throw new Error(typeof data.error === 'string' ? data.error : 'Unable to record report');
            }
            setFalsePositiveReportState('submitted');
            trackEvent('task_recovery_started', {
                method: 'false_positive_report',
                receiptId: governanceEvidence.receiptId,
                decision: governanceEvidence.decision,
                riskLevel: governanceEvidence.riskLevel,
                templateId,
            });
        } catch {
            setFalsePositiveReportState('error');
        }
    }, [canReportFalsePositive, error, governanceEvidence, templateId, templateName]);

    // W92-T1: Submit approval request
    const submitApprovalRequest = useCallback(async () => {
        if (!templateId || !intent) return;
        setApprovalSubmitting(true);
        try {
            const response = await fetch('/api/approvals', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    templateId: templateId || templateName,
                    templateName,
                    inputs,
                    intent,
                    ...(executionOverrides?.cvfPhase ? { cvfPhase: executionOverrides.cvfPhase } : {}),
                    ...(executionOverrides?.cvfRiskLevel ? { cvfRiskLevel: executionOverrides.cvfRiskLevel } : {}),
                    ...(executionProvider ? { provider: executionProvider } : {}),
                    ...(selectedModel ? { model: selectedModel } : {}),
                    reason: error || '',
                }),
            });
            const data = await response.json();
            if (data.success && data.id) {
                setApprovalRequestId(data.id);
                trackEvent('task_recovery_started', {
                    method: 'approval_request',
                    approvalId: data.id,
                    decision: 'NEEDS_APPROVAL',
                    templateId,
                });
            }
        } finally {
            setApprovalSubmitting(false);
        }
    }, [templateId, templateName, inputs, intent, error, executionOverrides?.cvfPhase, executionOverrides?.cvfRiskLevel, executionProvider, selectedModel]);

    const runMockExecution = useCallback((attempt: Attempt) => {
        const { isVi, request } = latest.current;
        const statuses = isVi
            ? [
                'Đang khởi tạo...',
                'Đang phân tích ý định...',
                'Đang tạo phản hồi...',
                'Đang kiểm tra chất lượng...',
                'Đang hoàn tất...',
            ]
            : [
                'Initializing...',
                'Parsing intent...',
                'Generating response...',
                'Applying quality checks...',
                'Finalizing output...',
            ];

        // Progress is tracked locally so no side effect runs inside a state updater.
        setStatus(statuses[0]);
        let value = 0;
        const interval = setInterval(() => {
            value += Math.random() * 15;
            setProgress(Math.min(value, 100));
            setStatus(statuses[Math.min(Math.floor(value / 25), statuses.length - 1)]);

            if (value >= 100) {
                clearInterval(interval);
                attempt.intervals.delete(interval);
                scheduleInAttempt(attempt, () => deliverOnce(attempt, latest.current.onComplete, [generateMockOutput(request.templateName)]), 500);
            }
        }, 300);
        attempt.intervals.add(interval);
    }, []);

    // W96-T1: auto-advance after 2000ms when completion state is set
    useEffect(() => {
        if (!completion) return;
        const timer = scheduleInAttempt(completion.attempt, () => deliverOnce(completion.attempt, latest.current.onComplete, [completion.output, completion.receipt]), 2000);
        return () => clearTimeout(timer);
    }, [completion]);

    // The attempt restarts only when the request content (taskKey) or settings readiness changes.
    useEffect(() => {
        if (!isLoaded) {
            return;
        }

        const attempt = createAttempt();
        attemptRef.current = attempt;
        scheduleInAttempt(attempt, () => {
            // A replaced attempt must not leave its results visible as the current attempt's UI.
            const { request } = latest.current;
            setProgress(0);
            setError(null);
            setGuidedResponse(null);
            setApprovalRequestId(null);
            setEnforcementStatus(null);
            setApprovalSafeHint(null);
            setFalsePositiveReportState('idle');
            setExecutionRiskLevel(null);
            setGovernanceEvidence(null);
            setExecutionDiagnostic(null);
            setCompletion(null);

            // Try real execution first if we have the required data
            if (request.inputs && request.intent && Object.keys(request.inputs).length > 0) {
                void executeReal(attempt);
            } else {
                // No inputs provided, use mock
                runMockExecution(attempt);
            }
        }, 0);

        return () => {
            stopAttempt(attempt);
            if (attemptRef.current === attempt) attemptRef.current = null;
        };
    }, [taskKey, isLoaded, executeReal, runMockExecution]);

    // Cancel invalidates the attempt, then forwards onCancel once per attempt.
    const handleCancel = useCallback(() => {
        const attempt = attemptRef.current;
        if (attempt) {
            if (attempt.cancelRequested) return;
            attempt.cancelRequested = true;
            stopAttempt(attempt);
        }
        latest.current.onCancel();
    }, []);

    return (
        <div className="min-h-[60vh] flex flex-col items-center justify-center">
            <div className="text-center">
                {/* Spinning icon */}
                <div className="w-20 h-20 mx-auto mb-8 relative">
                    <div className="absolute inset-0 rounded-full border-4 border-gray-200 dark:border-gray-700" />
                    <div
                        className="absolute inset-0 rounded-full border-4 border-blue-600 border-t-transparent animate-spin"
                    />
                    <div className="absolute inset-0 flex items-center justify-center text-3xl">
                        {isRealExecution ? '🤖' : '⏳'}
                    </div>
                </div>

                <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
                    {isRealExecution
                        ? (isVi ? 'AI Đang xử lý...' : 'AI Processing...')
                        : (isVi ? 'Đang xử lý...' : 'Processing...')}
                </h2>

                <p className="text-gray-600 dark:text-gray-400 mb-2" aria-live="polite">
                    {status}
                </p>

                {isRealExecution && (
                    <p className="text-xs text-emerald-600 dark:text-emerald-400 mb-4">
                        🔗 {isVi ? 'Đã kết nối AI' : 'Connected to AI Provider'}
                    </p>
                )}

                {error && !guidedResponse && (
                    <p className="text-sm text-amber-600 dark:text-amber-400 mb-4" role="alert" aria-live="assertive">
                        ⚠️ {error}{!isRealExecution ? ` — ${isVi ? 'Đang dùng chế độ demo' : 'Using demo mode'}` : ''}
                    </p>
                )}

                {guidedResponse && (
                    <div
                        className="mt-4 mb-4 mx-auto max-w-md rounded-lg border border-blue-200 dark:border-blue-700 bg-blue-50 dark:bg-blue-950 p-4 text-left"
                        role="alert"
                        aria-live="polite"
                        data-testid="guided-response-panel"
                    >
                        <p className="text-sm font-semibold text-blue-800 dark:text-blue-200 mb-2">
                            {isVi ? '💡 Bước an toàn tiếp theo' : '💡 Safe next step'}
                        </p>
                        <p className="text-xs text-red-600 dark:text-red-400 mb-3">
                            {isVi
                                ? `⚠️ Yêu cầu này cần xem lại: ${error}`
                                : `⚠️ This request needs review: ${error}`}
                        </p>
                        <p className="text-sm text-blue-900 dark:text-blue-100 whitespace-pre-wrap">
                            {guidedResponse}
                        </p>
                    </div>
                )}

                {executionDiagnostic && (
                    <div
                        className="mt-4 mb-4 mx-auto max-w-md rounded-lg border border-amber-200 bg-amber-50 p-4 text-left dark:border-amber-700 dark:bg-amber-950/40"
                        role="alert"
                        aria-live="assertive"
                        data-testid="execution-diagnostic-panel"
                    >
                        <p className="text-sm font-semibold text-amber-900 dark:text-amber-100">
                            {isVi ? 'Chẩn đoán lượt chạy' : 'Execution diagnostic'}
                        </p>
                        <p className="mt-2 text-sm text-amber-800 dark:text-amber-200">
                            {executionDiagnostic.safeMessage}
                        </p>
                        <div className="mt-3 grid grid-cols-2 gap-2 text-xs text-amber-700 dark:text-amber-300">
                            <p><span className="font-medium">Stage:</span> {executionDiagnostic.stage}</p>
                            <p><span className="font-medium">Class:</span> {executionDiagnostic.class}</p>
                            <p><span className="font-medium">{isVi ? 'Retry:' : 'Retry:'}</span> {executionDiagnostic.retryable ? (isVi ? 'có thể' : 'possible') : (isVi ? 'không nên' : 'not advised')}</p>
                            <p><span className="font-medium">{isVi ? 'Next:' : 'Next:'}</span> {executionDiagnostic.userAction}</p>
                        </div>
                        {(executionDiagnostic.receiptId || executionDiagnostic.traceId) && (
                            <div className="mt-3 space-y-1 text-[11px] text-amber-700 dark:text-amber-300">
                                {executionDiagnostic.receiptId && <p className="break-all"><span className="font-medium">Receipt:</span> {executionDiagnostic.receiptId}</p>}
                                {executionDiagnostic.traceId && <p className="break-all"><span className="font-medium">Trace:</span> {executionDiagnostic.traceId}</p>}
                            </div>
                        )}
