            expect(transport.fetchMock).toHaveBeenCalledTimes(2);
            expect(bodyOf(transport.fetchMock, 0).templateId).toBe('task_a');
            expect(bodyOf(transport.fetchMock, 1).templateId).toBe('task_b');
