import React from 'react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { ProcessingScreen } from '@/components/ProcessingScreen';
import { trackEvent } from '@/lib/analytics';
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { preferences: { defaultExportMode: 'governance' } }, isLoaded: true }) }));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en' }) }));
vi.mock('@/lib/enforcement-log', () => ({ logEnforcementDecision: vi.fn() }));
vi.mock('@/lib/analytics', () => ({ trackEvent: vi.fn() }));
const task = (id: string) => ({ templateId: id, templateName: id, inputs: { topic: id }, intent: id, onComplete: vi.fn(), onCancel: vi.fn() });
const denied = (id: string, decision: string) => ({ ok: false, json: async () => ({ success: false, error: 'Synthetic hold', enforcement: { status: decision, reasons: ['Synthetic'], riskGate: { riskLevel: 'R3', status: decision } }, governanceEvidenceReceipt: { receiptId: id, decision } }) });
const tick = async () => { await act(async () => { await vi.advanceTimersByTimeAsync(1); }); };
describe('Local independent abandoned recovery requests', () => {
  beforeEach(() => { vi.useFakeTimers(); vi.clearAllMocks(); });
  afterEach(() => { cleanup(); vi.clearAllTimers(); vi.useRealTimers(); vi.unstubAllGlobals(); });
  it('positive control: active approval remains usable and records its own id', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValueOnce(denied('A', 'NEEDS_APPROVAL')).mockResolvedValueOnce({ json: async () => ({ success: true, id: 'approval_A' }) }));
    render(<ProcessingScreen {...task('A')} />); await tick();
    await act(async () => { fireEvent.click(screen.getByTestId('submit-approval-btn')); });
    expect(screen.getByTestId('approval-status-panel').textContent).toContain('approval_A');
    expect(trackEvent).toHaveBeenCalledWith('task_recovery_started', expect.objectContaining({ approvalId: 'approval_A' }));
  });
  it('replacement B starts with enabled approval and never shows pending A approval id', async () => {
    let release!: (value: unknown) => void;
    const pending = new Promise(resolve => { release = resolve; });
    vi.stubGlobal('fetch', vi.fn().mockResolvedValueOnce(denied('A', 'NEEDS_APPROVAL')).mockReturnValueOnce(pending).mockResolvedValueOnce(denied('B', 'NEEDS_APPROVAL')));
    const view = render(<ProcessingScreen {...task('A')} />); await tick();
    fireEvent.click(screen.getByTestId('submit-approval-btn'));
    view.rerender(<ProcessingScreen {...task('B')} />); await tick();
    const enabledForB = !(screen.getByTestId('submit-approval-btn') as HTMLButtonElement).disabled;
    await act(async () => { release({ json: async () => ({ success: true, id: 'approval_A' }) }); });
    expect(screen.queryByTestId('approval-status-panel')).toBeNull();
    expect(enabledForB).toBe(true);
    expect(trackEvent).not.toHaveBeenCalledWith('task_recovery_started', expect.objectContaining({ approvalId: 'approval_A' }));
  });
  it('replacement B report remains unsubmitted when pending A report resolves', async () => {
    let release!: (value: unknown) => void;
    const pending = new Promise(resolve => { release = resolve; });
    vi.stubGlobal('fetch', vi.fn().mockResolvedValueOnce(denied('receipt_A', 'BLOCK')).mockReturnValueOnce(pending).mockResolvedValueOnce(denied('receipt_B', 'BLOCK')));
    const view = render(<ProcessingScreen {...task('A')} />); await tick();
    fireEvent.click(screen.getByTestId('report-false-positive-btn'));
    view.rerender(<ProcessingScreen {...task('B')} />); await tick();
    await act(async () => { release({ ok: true, json: async () => ({ success: true }) }); });
    expect(screen.getByTestId('report-false-positive-btn').textContent).toBe('Report false positive');
    expect(trackEvent).not.toHaveBeenCalledWith('task_recovery_started', expect.objectContaining({ receiptId: 'receipt_A' }));
  });
});

